/**
 * @name Zip Slip
 * @description Detects Zip Slip vulnerabilities where archive members are extracted to dangerous paths.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Archive member names from zipfile or tarfile
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() or
        call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember("getnames").getACall() or
        call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember("getmembers").getACall()
      ) and
      source = call
    )
    or
    // Iterating over ZipFile.infolist() or similar
    exists(DataFlow::Node iter |
       iter = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("infolist").getACall()
       and
       source = iter
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File open or os.path operations that might lead to writing
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip: Archive member $@ used in file operation.", source.getNode(), "archive member"
